function st(a){let gp=0,gl=0,w=0,e=0,pk=0,dd=0,ls=0,ml=0;for(let x of a){e+=x.r;if(x.r>0){gp+=x.r;w++;ls=0}else{gl+=-x.r;ls++;ml=Math.max(ml,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:a.length,wr:100*w/a.length,pf:gp/gl,net:e,dd,ls:ml}}const f=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${s.pf.toFixed(2)} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`;
